@sig trait MiningCommandDerivationOwner_Api {
  def id: Art.BridgeId
  def guard_resolution_Id : Art.PortId
  def mining_command_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var mining_command: Ore_Hold_Mining_Guard_Supervisor.MiningCommand.Type = $

  def put_mining_command(value : Ore_Hold_Mining_Guard_Supervisor.MiningCommand.Type) : Unit = {
    Contract(
      Modifies(mining_command),
      Ensures(
        mining_command == value
      )
    )
    Spec {
      mining_command = value
    }

    Art.putValue(mining_command_Id, Ore_Hold_Mining_Guard_Supervisor.MiningCommand_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class MiningCommandDerivationOwner_Initialization_Api (
  val id: Art.BridgeId,
  val guard_resolution_Id : Art.PortId,
  val mining_command_Id : Art.PortId) extends MiningCommandDerivationOwner_Api

@datatype class MiningCommandDerivationOwner_Operational_Api (
  val id: Art.BridgeId,
  val guard_resolution_Id : Art.PortId,
  val mining_command_Id : Art.PortId) extends MiningCommandDerivationOwner_Api {

  // Logika spec var representing port state for incoming data port
  @spec var guard_resolution: Ore_Hold_Mining_Guard_Supervisor.GuardResolution = $

  def get_guard_resolution() : Option[Ore_Hold_Mining_Guard_Supervisor.GuardResolution] = {
    Contract(
      Ensures(
        Res == Some(guard_resolution)
      )
    )
    val value : Option[Ore_Hold_Mining_Guard_Supervisor.GuardResolution] = Art.getValue(guard_resolution_Id) match {
